from abc import ABC
from os import PathLike
from pathlib import Path

from PIL import ImageFont

width_track, height_track_reserved = (380, 250)
width_chart, height_chart = (254, 64)
width_note, height_note = (54, 18)
width_arctap, height_arctap = (width_note, 12)
width_hold, height_hold = (width_note, 379)
additional_canvas_width = width_note * 2 + 10
margin_bg = additional_canvas_width // 2
width_gap = 2
width_chart_edge = 8
width_cover = height_cover = height_chart * 4 - margin_bg // 2
default_text_x = width_track - width_chart - width_gap * 2
default_text_size = 20
arc_sampling_rate = 10
resize = 4


class BaseTheme(ABC):
    custom_bg_dir_path = ""
    slogan = "Generated by ArcaeaChartRender & Yurisaki BOT"
    default_transparency_range = (100, 220)
    transparent_color = (255, 255, 255, 0)
    arc_red_color = (185, 118, 180)
    arc_blue_color = (76, 141, 184)
    arc_green_color = (35, 255, 108)
    arc_white_color = (220, 220, 220)
    arc_error_color = (0, 0, 0)
    arc_alpha = (0, 0, 0)
    arc_skyline_color = (144, 138, 144)
    arc_skyline_designant_color = (180, 100, 120)
    text_song_title_color = (222, 222, 222, 255)
    text_song_title_stroke_color = (70, 70, 70, 255)
    arctap_designant_mask_color = (200, 0, 0, 120)
    thickness_arc = 10
    thickness_skyline = 2
    font_Exo_SemiBold_20 = None
    font_Exo_SemiBold_40 = None
    font_Kazesawa_Regular_54 = None
    font_SourceHanMonoSC_Regular_40 = None
    font_SourceHanMonoSC_Regular_34 = None


