class ColorlessTheme(LightTheme):
    tile_path = ""


def configure_assets(
    assets_root: str | PathLike[str],
    cjk_font_path: str | PathLike[str] | None = None,
) -> None:
    """Configure theme files before creating a ``Render`` instance."""
    root = Path(assets_root)
    fonts = root / "Fonts"
    cjk_font = (
        Path(cjk_font_path) if cjk_font_path else fonts / "NotoSansCJKsc-Regular.otf"
    )

    BaseTheme.custom_bg_dir_path = str(root / "img" / "bg" / "1080")
    exo_font = str(fonts / "Exo-SemiBold.ttf")
    cjk_font_text = str(cjk_font)
    BaseTheme.font_Exo_SemiBold_20 = ImageFont.truetype(exo_font, 20)
    BaseTheme.font_Exo_SemiBold_40 = ImageFont.truetype(exo_font, 40)
    BaseTheme.font_Kazesawa_Regular_54 = ImageFont.truetype(cjk_font_text, 54)
    BaseTheme.font_SourceHanMonoSC_Regular_40 = ImageFont.truetype(cjk_font_text, 40)
    BaseTheme.font_SourceHanMonoSC_Regular_34 = ImageFont.truetype(cjk_font_text, 34)

    LightTheme.tile_path = str(root / "img" / "track.png")
    LightTheme.tap_path = str(root / "img" / "note.png")
    LightTheme.hold_path = str(root / "img" / "note_hold.png")
    LightTheme.arctap_path = str(root / "models" / "tap_l.png")
    LightTheme.arctap_sfx_path = str(root / "models" / "sfx_l_note.jpg")
    LightTheme.default_bg_path = str(root / "img" / "bg" / "1080" / "base_light.jpg")

    ConflictTheme.tile_path = str(root / "img" / "track_dark.png")
    ConflictTheme.tap_path = str(root / "img" / "note_dark.png")
    ConflictTheme.hold_path = str(root / "img" / "note_hold_dark.png")
    ConflictTheme.arctap_path = str(root / "models" / "tap_d.png")
    ConflictTheme.arctap_sfx_path = str(root / "models" / "sfx_d_note.jpg")
    ConflictTheme.default_bg_path = str(
        root / "img" / "bg" / "1080" / "base_conflict.jpg"
    )

    ColorlessTheme.tile_path = str(root / "img" / "track_colorless.png")
